    /**
     * Construct a set of Echidna blocks.
     * @param {Runtime} runtime - the Scratch 3.0 runtime.
     */
    constructor(runtime) {
        /**
         * The Scratch 3.0 runtime.
         * @type {Runtime}
         */
        this.runtime = runtime;
        this.connectionAlertHasBeenShowed = false;

        this.buttonStatus = {
            sr: 'release',
            sl: 'release'
        };

        this.joystick = {
            x: 0,
            y: 0
        };

        this.light = {
            level: 0
        };

        this.analogIn = {
            level: 0
        };

        this.accelerometer = {
            x: 0,
            y: 0
        };

        this.digitalInputs = {};
        this.analogInputs = {};

        this.tempScale = 0.48828125;

        //this._socket = io(window.location.hostname + ':' + 3000);
        this._socket = io('http://localhost:' + PORT);

        this.runtime.on(Runtime.PROJECT_LOADED, () => {
            console.log("Entro en run start");
            this._socket.emit('reset', {});
        });

        this._socket.on("connect_error", data => {
            let defaultMessage =
                `It seems that echidnalink applicaction is not running. I need it to talk to Echidna board. Click in the EchidnaScratch button to get some help`;
            let message =
                formatMessage({
                    id: 'echidna.linkdisconnected',
                    default: defaultMessage,
                    description: 'Echidnalink is not connected'
                });
            if (!this.connectionAlertHasBeenShowed) {
                this.connectionAlertHasBeenShowed = true;
                alert(message);
            }
        })

        /////////////////////
        //this._socket.emit('digitalInput', { id: 'd3' });
        this._socket.on('digitalInputValue', data => {
            //console.log(data);
            this.digitalInputs[data.id] = {
                active: true,
                value: data.value
            }
        });

        this._socket.on('analogInputValue', (data) => {
            //console.log(data);
            this.analogInputs[data.id] = {
                active: true,
                value: data.value
            }
        })

        ////////////////////


        this._socket.on('button', data => {
            console.log('client: button event received');
            console.log(data);
            this.buttonStatus[data.name] = data.action;
            console.log(this.buttonStatus);
        })

        this._socket.on('joystick', data => {
            //console.log(data);
            this.joystick.x = data.x;
            this.joystick.y = data.y;
        });

        this._socket.on('light', data => {
            this.light.level = data.level;
        })

        this._socket.on('analog_in', data => {
            this.analogIn.level = data.value;
        })

        this._socket.on('accelerometer', data => {
            //console.log(data);
            this.accelerometer.x = data.x;
            this.accelerometer.y = data.y;
        });


        // this._socket.on('button_read', data => {
        //     console.log(data);
        // })

        // Create a new MicroBit peripheral instance
        //this._peripheral = new Echidna(this.runtime, Scratch3EchidnaBlocks.EXTENSION_ID);
    }


